'use strict';
// The hosted and local editions share this UI. Media and models stay on the Mac.
const isLocal=['127.0.0.1','localhost'].includes(location.hostname);
const engine={url:isLocal?location.origin:'http://127.0.0.1:8765',token:sessionStorage.getItem('cjh-engine-token')||'',status:null,jobs:[],busy:false};
const jobNames={queued:'排队中',running:'执行中',succeeded:'完成待验收',partial:'部分完成',failed:'失败',cancelled:'已取消',interrupted:'已中断'};
async function api(path,body){
  const response=await fetch(engine.url+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+engine.token,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(20000)});
  const result=await response.json();if(!response.ok){const error=Error(result.error||'本机服务请求失败');error.status=response.status;throw error;}return result;
}
async function connectEngine(){
  if(engine.connectionRequest)return engine.connectionRequest;
  engine.connectionRequest=(async()=>{
   if(isLocal){const response=await fetch('/api/session',{headers:{'X-CJH-Local':'1'},signal:AbortSignal.timeout(10000)});const data=await response.json();if(!data.token)throw Error(data.error||'本机配对失败');engine.token=data.token;}
   engine.status=await api('/api/status');sessionStorage.setItem('cjh-engine-token',engine.token);await refreshJobs();render();toast('已连接本机服务；能力以检测结果为准');
  })();
  try{return await engine.connectionRequest;}finally{engine.connectionRequest=null;}
}
function engineBanner(){return `<div class="alert"><strong>${engine.status?'本机执行服务已连接':'接通本机，开始实际制作'}</strong> · <a href="#engines">分析、粗剪与包装执行中心 →</a><br><small>识别在本机后台运行，页面可继续使用。剪辑写入独立达芬奇项目，不覆盖原项目。</small></div>`;}
const previousRender=render;
render=function(){previousRender();const badge=document.querySelector('.projectbar>.badge');if(badge)badge.textContent=engine.status?'本机执行版 · 已连接':'本机执行版 · 待连接';if(['materials','speech','matching','packaging','overview'].includes(page))$('#app').insertAdjacentHTML('afterbegin',engineBanner());if(page==='engines')renderJobs();if(page==='speech')for(const b of document.querySelectorAll('[data-action="edit-segment"]'))b.insertAdjacentHTML('afterend',`<button class="text-button" data-engine="preview-segment" data-id="${esc(b.dataset.id)}">试听</button><button class="text-button" data-engine="move-up" data-id="${esc(b.dataset.id)}" aria-label="上移台词">↑</button><button class="text-button" data-engine="move-down" data-id="${esc(b.dataset.id)}" aria-label="下移台词">↓</button>`);if(page==='materials')for(const b of document.querySelectorAll('[data-action="edit-asset"]'))if(project().assets.find(a=>a.id===b.dataset.id)?.analysis)b.insertAdjacentHTML('afterend',`<button class="text-button" data-engine="asset-analysis" data-id="${esc(b.dataset.id)}">分析结果</button>`);};
descriptions.engines=['从分析，到真正落剪。','本机执行队列 · 原声转写 · 达芬奇多轨粗剪 · 综艺包装'];
descriptions.packaging=['把笑点，落到时间线上。','花字、人物放大与音效可在执行中心写入新达芬奇项目；其余保留人工处理标记。'];
pages.find(p=>p[0]==='engines')[2]='执行中心';
engines=function(){const s=engine.status,p=project(),registered=p.assets.filter(a=>a.localId),resolve=s?.resolve;
return `<div class="stats"><div class="stat"><div class="stat-top">本机执行服务</div><div class="stat-number" style="font-size:25px">${s?'已连接':'未连接'}</div><p>127.0.0.1 · 素材不上传</p></div><div class="stat"><div class="stat-top">达芬奇 Studio</div><div class="stat-number" style="font-size:25px">${resolve?.connected?'已连通':'待连接'}</div><p>${esc(resolve?.version||'请打开软件并开启 Local 外部脚本')}</p></div><div class="stat"><div class="stat-top">自动识别</div><div class="stat-number" style="font-size:25px">${s?'语音已接入':'待检测'}</div><p>说话人身份仍须人工确认</p></div><div class="stat"><div class="stat-top">本地视觉模型</div><div class="stat-number" style="font-size:25px">${s?.localModels?.length||0} 个</div><p>仅调用本地 Ollama，不上传抽帧</p></div></div>
<div class="grid"><div><section class="panel"><div class="panel-head"><h2>01 / 连接执行端</h2><button class="secondary" data-engine="connect">${s?'重新检测':'连接本机'}</button></div><div class="panel-pad">${isLocal?`<p class="subtle">当前在本机执行版。可直接操作；服务关闭后任务将无法继续。</p><button class="text-button" data-engine="pair">复制配对码，在云端工作台连接</button>`:`<p class="subtle">先在这台 Mac 双击「启动剪辑工作台.command」。在本机页面复制配对码，粘贴后连接。若浏览器拦截本地网络，请使用本机执行版；两个网址的项目记录需通过备份迁移。</p><div class="field"><label for="engine-token">本次启动的配对码（仅当前浏览器会话保存）</label><input id="engine-token" type="password" autocomplete="off" placeholder="粘贴本机页面复制的配对码"></div><a class="secondary" href="http://127.0.0.1:8765/#engines" target="_blank" rel="noopener">打开本机执行版 ↗</a>`}${resolve?.error?`<div class="alert warm">${esc(resolve.error)}</div>`:''}<p class="subtle" style="margin-top:12px">本地服务不会自动开机启动。无云端积分扣费，仍会占用本机算力和磁盘。</p></div></section>
<section class="panel"><div class="panel-head"><h2>02 / 真实素材分析</h2>${tag(registered.length+' 个已关联')}</div><div class="panel-pad"><div class="field"><label for="local-paths">本机素材文件或文件夹路径（每行一个）</label><textarea id="local-paths" rows="2" placeholder="从 Finder 复制路径后粘贴。只登记，不复制原视频。"></textarea></div><button class="secondary" data-engine="register">关联这些本机素材</button><div class="engine-assets">${registered.map(a=>`<label class="engine-choice"><input type="checkbox" name="analyze-asset" value="${esc(a.localId)}" checked> ${esc(a.name)} <small>${esc(a.group||'未分组')}</small></label>`).join('')||'<p class="subtle">浏览器预览导入不等于执行端关联；请先填写本地路径。</p>'}</div><div class="fields-row"><div class="field"><label for="asr-model">语音模型</label><select id="asr-model"><option value="base">Whisper base · 轻量（约145MB）</option><option value="resolve">达芬奇内置 · 说话人标签（需21.1+）</option><option value="small">small · 更重（约466MB）</option><option value="tiny">tiny · 快速试跑（约75MB）</option></select></div><div class="field"><label for="vision-model">视觉模型（可选）</label><select id="vision-model"><option value="">仅抽帧，不猜测菜名</option>${(s?.localModels||[]).map(m=>`<option value="${esc(m)}" ${m==='qwen3-vl:2b-instruct'?'selected':''}>${esc(m)}</option>`).join('')}</select></div></div><label class="engine-choice"><input type="checkbox" id="do-asr" checked> 转写音频（模型首次运行会下载，素材不上传）</label><button class="primary" data-engine="analyze">开始分析所选素材</button><p class="subtle" style="margin-top:12px">输出真实时间码、台词、三张抽帧。抽帧不等于全片动作识别；视觉菜名只是待确认候选。可选择达芬奇内置说话人检测，标签不代表真实身份。</p></div></section>
<section class="panel"><div class="panel-head"><h2>03 / 达芬奇粗剪 ＋ 包装</h2></div><div class="panel-pad"><p class="subtle">按「台词与角色」中保留片段的顺序生成 V1＋原声；已确认食物写入 V2（不带食物原声）；人物放大写入 V3；花字写入 V4。每次创建独立项目，旧项目不会被覆盖。</p><div class="fields-row" style="margin-top:16px"><div class="field"><label for="cut-fps">成片帧率</label><select id="cut-fps"><option>30</option><option>25</option><option>24</option><option>50</option><option>60</option></select></div><div class="field"><label for="cut-layout">画幅</label><select id="cut-layout"><option value="vertical">竖屏 1080 × 1920</option><option value="horizontal">横屏 1920 × 1080</option></select></div></div><div class="toolbar-group"><button class="secondary" data-engine="suggest">按脚本标出台词候选</button><button class="primary" data-engine="resolve">生成新达芬奇项目</button></div><p class="subtle" style="margin-top:12px">脚本对齐是文本相似度建议，不会自动保留台词。花字为预渲染透明视频（非可编辑 Text+）；人物为定值放大。音效需在包装表指定已关联文件。回放、音乐避让暂只写待处理标记。生成后需在达芬奇播放验收，尚不自动导出成片。</p></div></section></div>
<aside><section class="panel"><div class="panel-head"><h2>执行队列</h2><button class="text-button" data-engine="refresh">刷新</button></div><div class="panel-pad" id="engine-jobs"></div></section><div class="alert warm">完成 ≠ 审片通过。任务失败会显示真实原因；部分完成不会标成全部成功。服务重启后不会自动重跑或重复创建时间线。</div></aside></div>`;};
function renderJobs(){const box=$('#engine-jobs');if(!box)return;const jobs=engine.jobs.filter(j=>j.projectId===project().id).sort((a,b)=>b.created-a.created);box.innerHTML=jobs.map(j=>`<article class="engine-job"><div><strong>${j.kind==='analyze'?'素材分析':'达芬奇执行'}</strong> ${tag(jobNames[j.status]||j.status,j.status==='succeeded'?'green':j.status==='failed'?'orange':'neutral')}</div><small>${new Date(j.created*1000).toLocaleString('zh-CN')}</small><p>${esc(j.message)}</p>${j.result?.timeline?`<p>时间线：${esc(j.result.timeline)}<br>已写入 ${j.result.actual.length} 项 · ${j.result.verified.durationFrames} 帧</p>`:''}${(j.result?.warnings||[]).map(w=>`<p class="subtle">${esc(w)}</p>`).join('')}<div class="toolbar-group">${['succeeded','partial'].includes(j.status)?`<button class="text-button" data-engine="result" data-id="${esc(j.id)}">查看结果</button><button class="text-button" data-engine="adopt" data-id="${esc(j.id)}">${j.kind==='analyze'?'导入台词与分析':'同步已执行项'}</button>`:''}${['queued','running'].includes(j.status)&&!((j.kind==='resolve'||j.resolveASR)&&j.status==='running')?`<button class="text-button" data-engine="cancel" data-id="${esc(j.id)}">取消</button>`:''}</div></article>`).join('')||'<p class="subtle">当前项目暂无执行任务。这里展示的都是本地服务真实任务，不是演示进度。</p>';}
async function refreshJobs(){
 if(!engine.token&&!isLocal)return;
 if(engine.jobsRequest)return engine.jobsRequest;
 engine.jobsRequest=(async()=>{
  let response;
  try{response=await api('/api/jobs');}
  catch(error){
   if(error.status!==401||!isLocal)throw error;
   const session=await fetch('/api/session',{headers:{'X-CJH-Local':'1'},signal:AbortSignal.timeout(10000)});
   const data=await session.json();if(!session.ok||!data.token)throw Error('本机配对已失效，请重新连接');
   engine.token=data.token;sessionStorage.setItem('cjh-engine-token',data.token);response=await api('/api/jobs');
  }
  engine.jobs=response.jobs;engine.lastJobsAt=Date.now();engine.pollError='';renderJobs();
 })();
 try{return await engine.jobsRequest;}finally{engine.jobsRequest=null;}
}
function mergeAssets(items){const p=project();for(const a of items){let existing=p.assets.find(x=>x.localId===a.id)||p.assets.find(x=>!x.localId&&x.name===a.name&&x.size===a.size);if(existing)Object.assign(existing,{localId:a.id,path:a.path});else p.assets.push({...a,id:uid(),localId:a.id,kind:'待分类',group:'',dish:''});}save();}
function actualPlan(){const p=project(),d=plan();const resolveAsset=(id,name)=>{let a=p.assets.find(a=>a.id===id||a.localId===id);if(!a){const matches=p.assets.filter(a=>a.path===name||a.name===name);if(matches.length!==1)throw Error('素材无法唯一对应：'+name);a=matches[0];}if(!a.localId)throw Error('素材未关联本机执行端：'+a.name);return a.localId;};d.selectedSpeech=d.selectedSpeech.map(s=>({...s,assetId:resolveAsset(s.assetId,s.source)}));d.foodPlacements=d.foodPlacements.map(m=>({...m,assetId:resolveAsset(m.assetId,m.file)}));d.packaging=d.packaging.map(e=>({...e,assetId:e.assetId?resolveAsset(e.assetId,''):undefined}));return d;}
async function showJob(j){if(j.kind==='resolve'){openForm('达芬奇实际执行回执',`<pre class="engine-result">${esc(JSON.stringify(j.result,null,2))}</pre>`,()=>{});return;}openForm('素材分析结果（未确认）',j.result.items.map(i=>`<article class="engine-job"><h3>${esc(i.source)}</h3><p>${i.duration?.toFixed(1)||'—'} 秒 · ${i.width||'—'} × ${i.height||'—'} · ${i.segments.length} 条台词</p><div class="frame-grid">${(i.frames||[]).map(f=>`<figure><img data-frame="${esc(f.file)}" alt="${esc(i.source)} ${f.at.toFixed(1)} 秒抽帧"><figcaption>${f.at.toFixed(1)} 秒</figcaption></figure>`).join('')}</div>${i.vision?`<pre class="engine-result">${esc(JSON.stringify(i.vision,null,2))}</pre>`:''}${i.error?`<div class="alert warm">${esc(i.error)}</div>`:''}${i.warnings.map(w=>`<p class="subtle">${esc(w)}</p>`).join('')}<p>${esc(i.segments.map(s=>s.text).join(' '))}</p></article>`).join(''),()=>{});for(const img of document.querySelectorAll('[data-frame]')){try{const response=await fetch(engine.url+'/api/frame?file='+encodeURIComponent(img.dataset.frame),{headers:{Authorization:'Bearer '+engine.token}});if(response.ok){const url=URL.createObjectURL(await response.blob());img.src=url;img.onload=()=>URL.revokeObjectURL(url);}}catch{}}}
function adopt(j){const p=project();p.appliedJobs??=[];if(p.appliedJobs.includes(j.id))return toast('该任务已经导入，未重复添加');if(j.kind==='analyze'){for(const i of j.result.items){p.segments.push(...i.segments);const a=p.assets.find(a=>a.localId===i.assetId);if(a)a.analysis={duration:i.duration,vision:i.vision,frames:i.frames,error:i.error};}}else{const ids=new Set(j.result.actual.map(a=>a.effectId).filter(Boolean));for(const e of p.effects)if(ids.has(e.id))e.status='已执行待验收';}p.appliedJobs.push(j.id);save();render();toast(j.kind==='analyze'?'结果已导入，请到台词与角色页审核':'执行状态已同步，未自动勾选验收');}
function suggest(){const p=project();if(!p.script||!p.segments.length)throw Error('请先提供脚本和真实转写');const normalized=p.script.replace(/[\s\p{P}]/gu,'');let count=0;for(const s of p.segments){const text=s.text.replace(/[\s\p{P}]/gu,'');s.scriptCandidate=text.length>=4&&(normalized.includes(text)||Array.from({length:Math.max(0,text.length-5)},(_,i)=>text.slice(i,i+6)).some(t=>normalized.includes(t)));if(s.scriptCandidate)count++;}save();openForm('文本对齐候选 · 需要你决定',`<p class="subtle">找到 ${count} 条存在相同文本片段的候选。未改变任何「保留/排除」决定，也未识别角色；重复拍摄需人工挑选。</p>${p.segments.filter(s=>s.scriptCandidate).map(s=>`<p>${esc(s.source)} / ${tc(s.start)}：${esc(s.text)}</p>`).join('')}`,()=>{});}
document.addEventListener('click',async e=>{const button=e.target.closest('[data-engine]');if(!button)return;const action=button.dataset.engine;if(engine.busy)return toast('上一项请求正在处理');engine.busy=true;button.disabled=true;try{
 if(action==='connect'){if(!isLocal)engine.token=$('#engine-token')?.value.trim()||engine.token;await connectEngine();}
 else if(action==='pair'){await navigator.clipboard.writeText(engine.token);toast('配对码已复制；仅给自己的工作台使用，重启服务后失效');}
 else if(action==='register'){const paths=$('#local-paths').value.split('\n').map(s=>s.trim().replace(/^['"]|['"]$/g,'')).filter(Boolean);if(!paths.length)throw Error('请填写素材路径');const data=await api('/api/register',{paths});mergeAssets(data.assets);render();toast(`已关联 ${data.assets.length} 个本机素材`);}
 else if(action==='analyze'){const assetIds=[...document.querySelectorAll('[name="analyze-asset"]:checked')].map(e=>e.value);if(!assetIds.length)throw Error('请选择已关联素材');if($('#asr-model').value==='resolve'&&!confirm('达芬奇转写会创建独立分析项目并切换当前项目。确认已保存当前工作？'))return;await api('/api/jobs',{kind:'analyze',projectId:project().id,assetIds,model:$('#asr-model').value,asrEngine:$('#asr-model').value==='resolve'?'resolve':'whisper',visionModel:$('#vision-model').value,transcribe:$('#do-asr').checked,script:project().script});await refreshJobs();toast('分析已提交，页面可继续操作');}
 else if(action==='resolve'){const d=actualPlan();if(!engine.status?.resolve?.connected)throw Error('达芬奇未连接，请打开后重新检测');if(!confirm(`将在达芬奇创建独立项目：${d.selectedSpeech.length} 条人物片段、${d.foodPlacements.length} 处食物画面、${d.packaging.length} 项包装。\n\n不会覆盖旧项目，但会切换当前项目。确认已经保存当前工作并执行？`))return;await api('/api/jobs',{kind:'resolve',projectId:project().id,plan:d,fps:Number($('#cut-fps').value),vertical:$('#cut-layout').value==='vertical',confirmed:true});await refreshJobs();toast('已提交达芬奇执行任务');}
 else if(action==='jy-read'){engine.resolveSource=await api('/api/resolve-current');render();toast('已读取实际时间线，请核对名称和转换限制');}
 else if(action==='jy-export'){
   if(!engine.resolveSource)throw Error('请先读取当前达芬奇时间线');
   if(!$('#jy-ack')?.checked)throw Error('请先勾选已了解转换限制');
   if(!engine.status?.jianying?.available)throw Error('本机转换器尚未就绪，请更新本机服务并安装依赖');
   const openAfter=$('#jy-open-after').checked;
   if(!confirm(`导出达芬奇当前时间线：\n${engine.resolveSource.project}\n${engine.resolveSource.timeline}\n\n将新增独立剪映草稿，保留启用的音视频多轨和切点，不覆盖旧草稿。${openAfter?'完成后启动剪映。':''}\n调色、转场、关键帧及混音插件不会迁移。继续？`))return;
   await api('/api/jobs',{kind:'jianying',projectId:project().id,source:engine.resolveSource,name:engine.resolveSource.timeline,confirmed:true,ackLimitations:true,openAfter});
   await refreshJobs();toast('已提交剪映草稿转换；执行队列显示真实结果');
 }
 else if(action==='jy-open'){const r=await api('/api/jianying-open',{id:button.dataset.id});await refreshJobs();toast(r.note);}
 else if(action==='jy-result'){const j=engine.jobs.find(j=>j.id===button.dataset.id);openForm('剪映草稿转换回执',`<pre class="engine-result">${esc(JSON.stringify(j.result,null,2))}</pre>`,()=>{});}
 else if(action==='refresh')await refreshJobs();
 else if(action==='suggest')suggest();
 else if(action==='asset-analysis'){const a=project().assets.find(a=>a.id===button.dataset.id);await showJob({kind:'analyze',result:{items:[{source:a.name,segments:[],warnings:[],...a.analysis}]}});}
 else if(action==='preview-segment'){const p=project(),s=p.segments.find(s=>s.id===button.dataset.id),a=p.assets.find(a=>a.localId===s.assetId||a.id===s.assetId||a.path===s.source);if(!a)throw Error('请关联台词对应的原素材');await preview(a.id,s.start);}
 else if(action==='move-up'||action==='move-down'){const list=project().segments,i=list.findIndex(s=>s.id===button.dataset.id),next=i+(action==='move-up'?-1:1);if(next>=0&&next<list.length){[list[i],list[next]]=[list[next],list[i]];save();render();}}
 else if(action==='cancel'){await api('/api/cancel',{id:button.dataset.id});await refreshJobs();}
 else if(action==='result')await showJob(engine.jobs.find(j=>j.id===button.dataset.id));
 else if(action==='adopt')adopt(engine.jobs.find(j=>j.id===button.dataset.id));
 }catch(err){toast(err.message.includes('fetch')?'无法访问本机服务。请启动服务、允许本地网络访问，或打开本机执行版。':err.message);}finally{engine.busy=false;button.disabled=false;}});
// Extend the existing packaging editor with an actual local sound-file binding.
const priorEditEffect=editEffect;
editEffect=function(id){priorEditEffect(id);const p=project(),effect=p.effects.find(e=>e.id===id);$('#modal-fields').insertAdjacentHTML('beforeend',selectField('assetId','音效素材（类型为音效时使用）',effect?.assetId||'',[['','未指定：只生成待处理标记'],...p.assets.filter(a=>a.localId&&a.type.startsWith('audio')).map(a=>[a.id,a.name])]));const priorSave=modalSave;modalSave=v=>{priorSave(v);};};
const priorPreview=preview;
preview=async function(id,start){const a=project().assets.find(a=>a.id===id);if(!a?.localId||media.has(id))return priorPreview(id,start);try{const result=await api('/api/media-url?id='+encodeURIComponent(a.localId));if(a.type.startsWith('image'))return openForm('本机图片',`<img src="${esc(result.url)}" alt="${esc(a.name)}" style="max-width:100%;max-height:65vh">`,()=>{});$('#preview-title').textContent=a.name;$('#preview-note').textContent='本机原素材预览 · 不上传视频';$('#video').src=result.url;$('#video').onloadedmetadata=()=>{$('#video').currentTime=Math.min(num(start),$('#video').duration||0);};$('#preview').showModal();}catch(err){toast(err.message);}};
const oldHelp=$('#help').onclick;
$('#help').onclick=()=>openForm('本机执行版 · 使用说明','<ol class="help-list"><li>执行中心连接本机服务，登记素材路径。</li><li>选择素材启动转写；完成后查看抽帧、导入台词。</li><li>在台词与角色页确认身份、保留片段；顺序即粗剪顺序。</li><li>填写已确认的食物画面和综艺包装位置。</li><li>在执行中心生成独立达芬奇项目，播放验收。</li></ol><p>花字为预渲染透明视频；可选达芬奇说话人检测；身份仍需人工确认，暂不自动音乐避让或成片导出。模型错误须人工修正。云端与本机网址的浏览器记录独立，迁移请用项目备份。</p>',()=>{});
const renderBeforeJianying=render;
render=function(){renderBeforeJianying();if(page==='engines'){
 const jy=engine.status?.jianying,source=engine.resolveSource;
 const left=document.querySelector('#app .grid>div');
 if(left)left.insertAdjacentHTML('beforeend',`<section class="panel" id="jianying-step"><div class="panel-head"><h2>04 / 达芬奇粗剪 → 剪映包装</h2>${tag(jy?.app?'剪映 '+jy.app.version:'待检测')}</div><div class="panel-pad"><p class="subtle">读取达芬奇当前实际时间线，生成独立、多轨、可继续剪辑的剪映草稿。人物、食物、原声和音效分轨保留，不是导入一条压平的 MP4。</p><p style="margin-top:12px">${jy?.app?'已发现本机剪映专业版':'连接本机后检测剪映安装情况'} · ${jy?.available?'转换器就绪':'转换器待就绪'}</p><button class="secondary" data-engine="jy-read">读取当前达芬奇时间线</button>${source?`<div class="alert"><strong>${esc(source.project)}</strong><br>时间线：${esc(source.timeline)}<br><small>以任务执行时的实际内容为准；项目或时间线切换后会拒绝导出。</small></div>`:'<p class="subtle">先在达芬奇选中已经粗剪好的时间线，再点击读取。</p>'}<div class="alert warm">转换边界：保留切点、轨道位置、原素材及片段静态变换/音量。调色、转场、关键帧、音频插件和轨道混音不迁移；变速、Fusion、生成器等会阻止转换。预渲染花字仍是视频。草稿引用本机文件，素材不上传。剪映版本更新后需重新验证兼容性。</div><label class="engine-choice"><input id="jy-ack" type="checkbox">我了解转换限制，将在剪映检查画面和声音</label><label class="engine-choice"><input id="jy-open-after" type="checkbox" checked>导出后打开剪映（首页选择新草稿）</label><button class="primary" data-engine="jy-export" ${!source||!jy?.available?'disabled':''}>导出剪映草稿并继续包装</button><p class="subtle" style="margin-top:12px">新增草稿不覆盖原项目；不调用剪映助手或云端识别，也不会自动使用付费模板。若使用自定义草稿目录，请先恢复默认目录或联系配置。</p></div></section>`);
}};
const renderJobsBeforeJianying=renderJobs;
renderJobs=function(){renderJobsBeforeJianying();const box=$('#engine-jobs');if(!box)return;
 // Existing renderer handles analysis / Resolve; use a dedicated receipt for draft jobs.
 const jobs=engine.jobs.filter(j=>j.projectId===project().id).sort((a,b)=>b.created-a.created);
 [...box.querySelectorAll('.engine-job')].forEach((card,i)=>{const j=jobs[i];if(j.kind!=='jianying')return;
 card.innerHTML=`<div><strong>剪映草稿转换</strong> ${tag(jobNames[j.status]||j.status,j.status==='failed'?'orange':'neutral')}</div><small>${new Date(j.created*1000).toLocaleString('zh-CN')}</small><p>${esc(j.message)}</p>${j.result?.draftPath?`<p><strong>${esc(j.result.draftName)}</strong><br>${j.result.clipCount} 个片段 · ${j.result.tracks.length} 条轨道 · ${j.result.duration.toFixed(2)} 秒</p><p class="subtle" style="overflow-wrap:anywhere">${esc(j.result.draftPath)}</p><p class="subtle">${j.result.opened?'已请求启动剪映，请在首页选择此草稿。':'草稿已保存，可点击下方打开剪映。'} 尚未自动判定审片通过。</p><button class="secondary" data-engine="jy-open" data-id="${esc(j.id)}">打开剪映</button> <button class="text-button" data-engine="jy-result" data-id="${esc(j.id)}">转换报告</button>`:''}${j.status==='queued'?`<button class="text-button" data-engine="cancel" data-id="${esc(j.id)}">取消</button>`:''}`;
 });};
setInterval(()=>{if(isLocal||engine.token)(engine.status?refreshJobs():connectEngine()).catch(error=>{engine.pollError=error.message;if(typeof renderQuickProgress==='function')renderQuickProgress();});},4000);
render();
if(isLocal||engine.token)connectEngine().catch(()=>{engine.status=null;render();});
